  1→/* ── SUPER DUPER Chat Renderer ──────────────────────────────────────
  2→ *  Text rendering (Phase 1) + Panel component factories (Phase 2).
  3→ *  No innerHTML anywhere — all DOM built via createElement + textContent.
  4→ * ──────────────────────────────────────────────────────────────────── */
  5→
  6→// ── Slot Colors ────────────────────────────────────────────────────
  7→
  8→export const SLOT_COLORS = {
  9→  clip:         { color: "#FFD500", varName: "--sd-slot-clip" },
 10→  clip_vision:  { color: "#A8DADC", varName: "--sd-slot-clip-vision" },
 11→  conditioning: { color: "#FFA931", varName: "--sd-slot-conditioning" },
 12→  controlnet:   { color: "#6EE7B7", varName: "--sd-slot-controlnet" },
 13→  image:        { color: "#64B5F6", varName: "--sd-slot-image" },
 14→  latent:       { color: "#FF9CF9", varName: "--sd-slot-latent" },
 15→  mask:         { color: "#81C784", varName: "--sd-slot-mask" },
 16→  model:        { color: "#B39DDB", varName: "--sd-slot-model" },
 17→  style_model:  { color: "#C2FFAE", varName: "--sd-slot-style-model" },
 18→  vae:          { color: "#FF6E6E", varName: "--sd-slot-vae" },
 19→  noise:        { color: "#B0B0B0", varName: "--sd-slot-noise" },
 20→  guider:       { color: "#66FFFF", varName: "--sd-slot-guider" },
 21→  sampler:      { color: "#ECB4B4", varName: "--sd-slot-sampler" },
 22→  sigmas:       { color: "#CDFFCD", varName: "--sd-slot-sigmas" },
 23→};
 24→
 25→function _slotColor(slotType) {
 26→  const s = SLOT_COLORS[slotType];
 27→  return s ? s.color : "#9a9caa";
 28→}
 29→
 30→// ── Text Rendering ─────────────────────────────────────────────────
 31→
 32→/**
 33→ * Parse raw text into a DocumentFragment with styled elements.
 34→ * Handles: ```code blocks```, `inline code`, **bold**, paragraph breaks.
 35→ * NO innerHTML — all content via textContent.
 36→ */
 37→export function renderText(rawText) {
 38→  const frag = document.createDocumentFragment();
 39→  if (!rawText) return frag;
 40→
 41→  // Split on triple-backtick code blocks
 42→  const parts = rawText.split(/(```[\s\S]*?```)/);
 43→
 44→  for (const part of parts) {
 45→    if (part.startsWith("```") && part.endsWith("```")) {
 46→      // Code block — strip fences and optional language tag
 47→      let code = part.slice(3, -3);
 48→      // Remove optional language identifier on first line
 49→      const nlIdx = code.indexOf("\n");
 50→      if (nlIdx !== -1 && nlIdx < 20 && /^[a-zA-Z]*$/.test(code.slice(0, nlIdx).trim())) {
 51→        code = code.slice(nlIdx + 1);
 52→      }
 53→      // Trim leading/trailing newline
 54→      if (code.startsWith("\n")) code = code.slice(1);
 55→      if (code.endsWith("\n")) code = code.slice(0, -1);
 56→
 57→      const pre = document.createElement("pre");
 58→      pre.className = "sd-code-block";
 59→      pre.textContent = code;
 60→      frag.appendChild(pre);
 61→    } else {
 62→      // Text content — split into paragraphs on double newlines
 63→      const paragraphs = part.split(/\n{2,}/);
 64→      for (const para of paragraphs) {
 65→        const trimmed = para.trim();
 66→        if (!trimmed) continue;
 67→
 68→        const p = document.createElement("p");
 69→        _appendInlineMarkup(p, trimmed);
 70→        if (trimmed.length > 200) {
 71→          p.classList.add("sd-para-long");
 72→        }
 73→        frag.appendChild(p);
 74→      }
 75→    }
 76→  }
 77→
 78→  return frag;
 79→}
 80→
 81→/**
 82→ * Parse inline markup (**bold** and `code`) and append nodes to parent.
 83→ */
 84→function _appendInlineMarkup(parent, text) {
 85→  // Tokenize on **bold** and `code` patterns
 86→  const tokens = text.split(/(\*\*[^*]+\*\*|`[^`]+`)/);
 87→
 88→  for (const token of tokens) {
 89→    if (token.startsWith("**") && token.endsWith("**")) {
 90→      // Bold
 91→      const strong = document.createElement("strong");
 92→      strong.className = "sd-text-bold";
 93→      strong.textContent = token.slice(2, -2);
 94→      parent.appendChild(strong);
 95→    } else if (token.startsWith("`") && token.endsWith("`")) {
 96→      // Inline code
 97→      const code = document.createElement("code");
 98→      code.className = "sd-code-inline";
 99→      code.textContent = token.slice(1, -1);
100→      parent.appendChild(code);
101→    } else if (token) {
102→      _appendInlineText(parent, token);
103→    }
104→  }
105→}
106→
107→/**
108→ * Append plain text, converting single newlines to <br>.
109→ */
110→function _appendInlineText(parent, text) {
111→  const lines = text.split("\n");
112→  for (let i = 0; i < lines.length; i++) {
113→    if (i > 0) parent.appendChild(document.createElement("br"));
114→    if (lines[i]) parent.appendChild(document.createTextNode(lines[i]));
115→  }
116→}
117→
118→// ── Typing Indicator ───────────────────────────────────────────────
119→
120→export function createTypingIndicator() {
121→  const el = document.createElement("span");
122→  el.className = "sd-typing";
123→  for (let i = 0; i < 3; i++) {
124→    const dot = document.createElement("span");
125→    dot.className = "sd-typing__dot";
126→    el.appendChild(dot);
127→  }
128→  return el;
129→}
130→
131→// ── Panel Component Factories ──────────────────────────────────────
132→
133→/**
134→ * Create a colored slot tag chip.
135→ * @param {string} label - Node/concept name
136→ * @param {string} slotType - Slot type key (e.g., "model", "vae")
137→ */
138→export function createSlotTag(label, slotType) {
139→  const color = _slotColor(slotType);
140→  const tag = document.createElement("span");
141→  tag.className = "sd-slot-tag";
142→  tag.style.background = color + "1f"; // 12% opacity
143→  tag.style.border = `1px solid ${color}40`; // 25% opacity
144→  tag.style.color = color;
145→
146→  const dot = document.createElement("span");
147→  dot.className = "sd-slot-tag__dot";
148→  dot.style.background = color;
149→  dot.style.boxShadow = `0 0 4px ${color}8c`; // 55% glow
150→  tag.appendChild(dot);
151→
152→  const txt = document.createTextNode(label);
153→  tag.appendChild(txt);
154→
155→  return tag;
156→}
157→
158→/**
159→ * Create an interactive node pill for inline display.
160→ * Shows node class_type with slot-appropriate color.
161→ * Data attributes enable canvas highlighting from sidebar.js.
162→ *
163→ * @param {string} classType - Node class_type (e.g., "KSampler")
164→ * @param {string} slotType - Slot type key (e.g., "sampler")
165→ * @param {string|null} nodeId - Node ID for canvas highlighting
166→ */
167→export function createNodePill(classType, slotType, nodeId) {
168→  const color = _slotColor(slotType);
169→  const pill = document.createElement("span");
170→  pill.className = "sd-node-pill";
171→  pill.style.setProperty("--pill-color", color);
172→
173→  // Data attributes for canvas interaction (wired in sidebar.js)
174→  if (nodeId) {
175→    pill.dataset.nodeId = nodeId;
176→    pill.style.cursor = "pointer";
177→    pill.title = `${classType} (node #${nodeId}) — click to select on canvas`;
178→  } else {
179→    pill.title = classType;
180→  }
181→  pill.dataset.classType = classType;
182→
183→  // Colored dot
184→  const dot = document.createElement("span");
185→  dot.className = "sd-node-pill__dot";
186→  pill.appendChild(dot);
187→
188→  // Label — strip common verbose suffixes for readability
189→  const shortName = classType
190→    .replace(/Simple$/, "")
191→    .replace(/Advanced$/, "")
192→    .replace(/^ComfyUI_/, "");
193→  const label = document.createTextNode(shortName);
194→  pill.appendChild(label);
195→
196→  return pill;
197→}
198→
199→/**
200→ * Create a collapsible section.
201→ * @param {string} title
202→ * @param {string} dotColor - CSS color string
203→ * @param {number|string} count - Badge count
204→ * @param {boolean} defaultOpen
205→ * @param {Function} buildBody - () => HTMLElement (lazy, called on first expand)
206→ */
207→export function createCollapsibleSection(title, dotColor, count, defaultOpen, buildBody) {
208→  const section = document.createElement("div");
209→  section.className = "sd-section" + (defaultOpen ? " sd-section--open" : "");
210→
211→  // Trigger button
212→  const trigger = document.createElement("button");
213→  trigger.className = "sd-section__trigger";
214→
215→  const dot = document.createElement("span");
216→  dot.className = "sd-section__dot";
217→  dot.style.background = dotColor;
218→  dot.style.boxShadow = `0 0 4px ${dotColor}8c`;
219→  trigger.appendChild(dot);
220→
221→  const titleEl = document.createElement("span");
222→  titleEl.className = "sd-section__title";
223→  titleEl.textContent = title;
224→  trigger.appendChild(titleEl);
225→
226→  if (count != null) {
227→    const countEl = document.createElement("span");
228→    countEl.className = "sd-section__count";
229→    countEl.textContent = String(count);
230→    trigger.appendChild(countEl);
231→  }
232→
233→  const chevron = document.createElement("span");
234→  chevron.className = "sd-section__chevron";
235→  chevron.textContent = "\u25b8"; // right-pointing triangle
236→  trigger.appendChild(chevron);
237→
238→  section.appendChild(trigger);
239→
240→  // Body (lazy)
241→  const body = document.createElement("div");
242→  body.className = "sd-section__body";
243→  let built = defaultOpen;
244→  if (defaultOpen && buildBody) {
245→    const content = buildBody();
246→    if (content) body.appendChild(content);
247→  }
248→  section.appendChild(body);
249→
250→  // Toggle
251→  trigger.addEventListener("click", () => {
252→    const isOpen = section.classList.toggle("sd-section--open");
253→    if (isOpen && !built && buildBody) {
254→      built = true;
255→      const content = buildBody();
256→      if (content) body.appendChild(content);
257→    }
258→  });
259→
260→  return section;
261→}
262→
263→/**
264→ * Create a flow chain showing signal path through nodes.
265→ * @param {Array<{label: string, slotType: string}>} nodes
266→ * @param {string} [pathLabel] - Optional path label prefix
267→ */
268→export function createFlowChain(nodes, pathLabel) {
269→  const chain = document.createElement("div");
270→  chain.className = "sd-flow-chain";
271→
272→  if (pathLabel) {
273→    const lbl = document.createElement("span");
274→    lbl.className = "sd-flow-chain__label";
275→    lbl.textContent = pathLabel;
276→    chain.appendChild(lbl);
277→  }
278→
279→  for (let i = 0; i < nodes.length; i++) {
280→    if (i > 0) {
281→      const arrow = document.createElement("span");
282→      arrow.className = "sd-flow-chain__arrow";
283→      arrow.textContent = "\u2192"; // →
284→      chain.appendChild(arrow);
285→    }
286→
287→    const node = document.createElement("span");
288→    node.className = "sd-flow-chain__node";
289→    const color = _slotColor(nodes[i].slotType);
290→    node.style.color = color;
291→    node.style.background = color + "1a"; // ~10% opacity
292→    node.textContent = nodes[i].label;
293→    chain.appendChild(node);
294→  }
295→
296→  return chain;
297→}
298→
299→/**
300→ * Create a key-value detail row with dotted leader.
301→ * @param {string} label
302→ * @param {string} value
303→ */
304→export function createDetailRow(label, value) {
305→  const row = document.createElement("div");
306→  row.className = "sd-detail-row";
307→
308→  const lbl = document.createElement("span");
309→  lbl.className = "sd-detail-row__label";
310→  lbl.textContent = label;
311→  row.appendChild(lbl);
312→
313→  const leader = document.createElement("span");
314→  leader.className = "sd-detail-row__leader";
315→  row.appendChild(leader);
316→
317→  const val = document.createElement("span");
318→  val.className = "sd-detail-row__value";
319→  val.textContent = value;
320→  row.appendChild(val);
321→
322→  return row;
323→}
324→
325→/**
326→ * Create a capability row.
327→ * @param {string} label
328→ * @param {string} desc
329→ * @param {string} [color] - Dot color, defaults to brand
330→ */
331→export function createCapabilityRow(label, desc, color) {
332→  const row = document.createElement("div");
333→  row.className = "sd-capability-row";
334→
335→  const dot = document.createElement("span");
336→  dot.className = "sd-capability-row__dot";
337→  dot.style.background = color || "var(--sd-brand)";
338→  row.appendChild(dot);
339→
340→  const lbl = document.createElement("span");
341→  lbl.className = "sd-capability-row__label";
342→  lbl.textContent = label;
343→  row.appendChild(lbl);
344→
345→  const sep = document.createElement("span");
346→  sep.className = "sd-capability-row__sep";
347→  row.appendChild(sep);
348→
349→  const d = document.createElement("span");
350→  d.className = "sd-capability-row__desc";
351→  d.textContent = desc;
352→  row.appendChild(d);
353→
354→  return row;
355→}
356→
357→/**
358→ * Create an action footer.
359→ * @param {string} status - Status text
360→ * @param {Array<{label: string, variant: string}>} actions - Buttons
361→ */
362→export function createActionFooter(status, actions) {
363→  const footer = document.createElement("div");
364→  footer.className = "sd-panel__footer";
365→
366→  const statusEl = document.createElement("span");
367→  statusEl.className = "sd-panel__footer-status";
368→  statusEl.textContent = status || "";
369→  footer.appendChild(statusEl);
370→
371→  if (actions && actions.length) {
372→    const actionsEl = document.createElement("div");
373→    actionsEl.className = "sd-panel__footer-actions";
374→    for (const action of actions) {
375→      const btn = document.createElement("button");
376→      btn.className = `sd-btn sd-btn--${action.variant || "secondary"}`;
377→      btn.textContent = action.label;
378→      actionsEl.appendChild(btn);
379→    }
380→    footer.appendChild(actionsEl);
381→  }
382→
383→  return footer;
384→}
385→
386→/**
387→ * Create a full panel from panelData.
388→ * @param {Object} panelData - Panel schema from backend
389→ * @returns {HTMLElement|null}
390→ *
391→ * panelData schema:
392→ * {
393→ *   type: "workflow_analysis"|"discovery"|"execution"|"error",
394→ *   header: { label, badge, title, summary, stats: [{value,label}] },
395→ *   sections: [{
396→ *     title, dotColor, count, defaultOpen,
397→ *     type: "flow_chain"|"slot_tags"|"capability_rows"|"detail_rows",
398→ *     data: { ... type-specific ... }
399→ *   }],
400→ *   footer: { status, actions: [{label,variant}] }
401→ * }
402→ */
403→export function createPanel(panelData) {
404→  if (!panelData) return null;
405→
406→  const panel = document.createElement("div");
407→  panel.className = "sd-panel";
408→
409→  // Header
410→  if (panelData.header) {
411→    const header = document.createElement("div");
412→    header.className = "sd-panel__header";
413→
414→    // Label row
415→    const labelRow = document.createElement("div");
416→    labelRow.className = "sd-panel__label-row";
417→
418→    const label = document.createElement("span");
419→    label.className = "sd-panel__label";
420→    label.textContent = panelData.header.label || "";
421→    labelRow.appendChild(label);
422→
423→    if (panelData.header.badge) {
424→      const badge = document.createElement("span");
425→      badge.className = "sd-panel__badge";
426→      badge.textContent = panelData.header.badge;
427→      labelRow.appendChild(badge);
428→    }
429→    header.appendChild(labelRow);
430→
431→    // Title
432→    if (panelData.header.title) {
433→      const title = document.createElement("div");
434→      title.className = "sd-panel__title";
435→      title.textContent = panelData.header.title;
436→      header.appendChild(title);
437→    }
438→
439→    // Summary
440→    if (panelData.header.summary) {
441→      const summary = document.createElement("div");
442→      summary.className = "sd-panel__summary";
443→      summary.textContent = panelData.header.summary;
444→      header.appendChild(summary);
445→    }
446→
447→    // Stats
448→    if (panelData.header.stats && panelData.header.stats.length) {
449→      const stats = document.createElement("div");
450→      stats.className = "sd-panel__stats";
451→      for (const s of panelData.header.stats) {
452→        const stat = document.createElement("div");
453→        stat.className = "sd-panel__stat";
454→
455→        const val = document.createElement("span");
456→        val.className = "sd-panel__stat-value";
457→        val.textContent = String(s.value);
458→        stat.appendChild(val);
459→
460→        const lbl = document.createElement("span");
461→        lbl.className = "sd-panel__stat-label";
462→        lbl.textContent = s.label;
463→        stat.appendChild(lbl);
464→
465→        stats.appendChild(stat);
466→      }
467→      header.appendChild(stats);
468→    }
469→
470→    panel.appendChild(header);
471→  }
472→
473→  // Sections
474→  if (panelData.sections) {
475→    for (const sec of panelData.sections) {
476→      const dotColor = sec.dotColor || "var(--sd-brand)";
477→      const section = createCollapsibleSection(
478→        sec.title,
479→        dotColor,
480→        sec.count,
481→        sec.defaultOpen || false,
482→        () => _buildSectionBody(sec)
483→      );
484→      panel.appendChild(section);
485→    }
486→  }
487→
488→  // Footer
489→  if (panelData.footer) {
490→    const footer = createActionFooter(
491→      panelData.footer.status,
492→      panelData.footer.actions
493→    );
494→    panel.appendChild(footer);
495→  }
496→
497→  return panel;
498→}
499→
500→/**
501→ * Build the body content for a section based on its type.
502→ */
503→function _buildSectionBody(sec) {
504→  const container = document.createDocumentFragment();
505→
506→  switch (sec.type) {
507→    case "flow_chain": {
508→      const chains = sec.data.chains || [sec.data];
509→      for (const chainData of chains) {
510→        const nodes = (chainData.nodes || []).map(n =>
511→          typeof n === "string" ? { label: n, slotType: "model" } : n
512→        );
513→        container.appendChild(createFlowChain(nodes, chainData.label));
514→      }
515→      break;
516→    }
517→
518→    case "slot_tags": {
519→      const wrap = document.createElement("div");
520→      wrap.className = "sd-slot-tags";
521→      for (const tag of (sec.data.tags || [])) {
522→        wrap.appendChild(createSlotTag(tag.label, tag.slotType));
523→      }
524→      container.appendChild(wrap);
525→      break;
526→    }
527→
528→    case "detail_rows": {
529→      for (const row of (sec.data.rows || [])) {
530→        container.appendChild(createDetailRow(row.label, row.value));
531→      }
532→      break;
533→    }
534→
535→    case "capability_rows": {
536→      for (const row of (sec.data.rows || [])) {
