406→        }
407→        break;
408→      }
409→
410→      case "stage":
411→        setStage(data.stage, data.detail, data.nodes_touched);
412→
413→        // Show node interaction indicator in chat
414→        if (data.nodes_touched && data.nodes_touched.length > 0 && data.stage !== "DONE") {
415→          const nodeMsg = document.createElement("div");
416→          nodeMsg.className = "sd-message sd-message--node-activity";
